import os
import base64
from typing import Dict, Any, Optional

import boto3
from botocore.exceptions import ClientError


class EnvelopeEncryptionError(Exception):
    pass


class KMSEnvelopeEncryptor:
    def __init__(self, key_id: str, region_name: Optional[str] = None):
        self.key_id = key_id
        self.kms = boto3.client(
            "kms",
            region_name=region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION"),
        )

    def encrypt(
        self,
        plaintext: bytes,
        encryption_context: Optional[Dict[str, str]] = None,
    ) -> Dict[str, Any]:
        try:
            data_key_response = self.kms.generate_data_key(
                KeyId=self.key_id,
                KeySpec="AES_256",
                EncryptionContext=encryption_context or {},
            )
            plaintext_data_key = data_key_response["Plaintext"]
            encrypted_data_key = data_key_response["CiphertextBlob"]

            ciphertext = self._aes_gcm_encrypt(plaintext_data_key, plaintext)

            return {
                "provider": "aws-kms",
                "key_id": self.key_id,
                "encrypted_data_key": base64.b64encode(encrypted_data_key).decode("utf-8"),
                "ciphertext": base64.b64encode(ciphertext).decode("utf-8"),
                "encryption_context": encryption_context or {},
                "algorithm": "AES-256-GCM",
            }
        except ClientError as e:
            raise EnvelopeEncryptionError(f"AWS KMS error during encrypt: {e}") from e

    def decrypt(self, envelope: Dict[str, Any]) -> bytes:
        try:
            encrypted_data_key = base64.b64decode(envelope["encrypted_data_key"])
            ciphertext = base64.b64decode(envelope["ciphertext"])
            encryption_context = envelope.get("encryption_context") or {}

            decrypt_response = self.kms.decrypt(
                CiphertextBlob=encrypted_data_key,
                EncryptionContext=encryption_context,
            )
            plaintext_data_key = decrypt_response["Plaintext"]

            return self._aes_gcm_decrypt(plaintext_data_key, ciphertext)
        except ClientError as e:
            raise EnvelopeEncryptionError(f"AWS KMS error during decrypt: {e}") from e
        except Exception as e:
            raise EnvelopeEncryptionError(f"Envelope decrypt failed: {e}") from e

    @staticmethod
    def _aes_gcm_encrypt(key: bytes, plaintext: bytes) -> bytes:
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except ImportError as e:
            raise EnvelopeEncryptionError("cryptography package is required") from e

        nonce = os.urandom(12)
        aesgcm = AESGCM(key)
        ciphertext = aesgcm.encrypt(nonce, plaintext, None)
        return nonce + ciphertext

    @staticmethod
    def _aes_gcm_decrypt(key: bytes, combined: bytes) -> bytes:
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except ImportError as e:
            raise EnvelopeEncryptionError("cryptography package is required") from e

        if len(combined) < 13:
            raise EnvelopeEncryptionError("Invalid ciphertext payload")

        nonce = combined[:12]
        ciphertext = combined[12:]
        aesgcm = AESGCM(key)
        return aesgcm.decrypt(nonce, ciphertext, None)
